import subprocess,json,os
from pathlib import Path
root=Path('/srv/projects')
result={'projects':{},'uid':os.geteuid()}
for p in sorted(root.iterdir()):
 if not p.is_dir() or p.is_symlink():continue
 def cmd(*a):
  try:
   q=subprocess.run(['git','-c','safe.directory='+str(p),'-C',str(p),*a],capture_output=True,text=True,timeout=9)
   return q.returncode,q.stdout.strip()[:300]
  except Exception:return 99,''
 v={'name':p.name,'has_git':False,'is_worktree':False,'private_runtime':[]}
 try:v['has_git']=(p/'.git').exists() or (p/'.git').is_symlink()
 except Exception:pass
 code,txt=cmd('rev-parse','--show-toplevel')
 v['is_worktree']=code==0 and txt==str(p)
 if v['is_worktree']:
  code,remote=cmd('config','--get','remote.origin.url')
  if '@' in remote and not remote.startswith('git@github.com:'):remote='[redacted credential URL]'
  v['origin']=remote
  v['sha']=cmd('rev-parse','HEAD')[1]
  v['branch']=cmd('branch','--show-current')[1]
  v['tracked_changes']=len(cmd('status','--porcelain','--untracked-files=no')[1].splitlines())
 for name in ('archive','releases','current','.venv','backend/.venv','.pm2','tools/pm2','private','data','backups','.runtime/npm/rea'):
  z=p/name
  try:
   if z.is_dir() or z.is_symlink():v['private_runtime'].append(name)
  except Exception:pass
 result['projects'][p.name]=v
print(json.dumps(result,separators=(',',':')))
